export const AUTONOMY = ["autonomous", "ai-led", "collaborative", "ai-assisted", "search-scaffold", "retrieval"];
export const SOURCE_KINDS = ["research", "announcement", "coverage", "commentary", "challenge"];
export const FIELDS = ["archaeology", "astronomy", "biology", "chemistry", "climate", "computer-science", "economics", "engineering", "materials", "mathematics", "medicine", "neuroscience", "physics"];
